// ❌ OLD: Manually switching tags with nested ternaries is verbose
// and forces code duplication for shared attributes/children.
import { createSignal } from 'solid-js';

export default function HeadingLegacy({ level, children }) {
  return (
    <div>
      {level() === 'h1' ? (
        <h1 class="title">{children}</h1>
      ) : level() === 'h2' ? (
        <h2 class="title">{children}</h2>
      ) : (
        <h3 class="title">{children}</h3>
      )}
    </div>
  );
}

import { Dynamic } from 'solid-js/web';

// ✅ NEW: <Dynamic> cleanly switches between string tags ('h1', 'h2')
// or component functions without repeating props or children markup.
export default function HeadingModern({ level, children }) {
  return (
    <Dynamic component={level()} class="title">
      {children}
    </Dynamic>
  );
}
